def line_cells(a_name, b_name):
    """绿色线两端点 -> 途经单元格集合(含端点, 仅支持横/竖线)"""
    ra, ca = name2rc(a_name)
    rb, cb = name2rc(b_name)
    cells = []
    if ca == cb:
        for r in range(min(ra, rb), max(ra, rb) + 1):
            cells.append((r, ca))
    elif ra == rb:
        for c in range(min(ca, cb), max(ca, cb) + 1):
            cells.append((ra, c))
    else:
        raise ValueError("绿线必须是横线或竖线")
    return cells

def _sample_mine_zone(rng, used):
    """随机采样一块 3x4 地雷区(内部空闲格数足够放地雷)"""
    for _ in range(60):
        r0 = rng.randrange(ROWS - MINE_ZONE_ROWS + 1)
        c0 = rng.randrange(COLS - MINE_ZONE_COLS + 1)
        cells = [(r, c) for r in range(r0, r0 + MINE_ZONE_ROWS)
                 for c in range(c0, c0 + MINE_ZONE_COLS) if (r, c) not in used]
        if len(cells) >= EXPLOSIVES_N:
            return cells
    return None

def _truth_ok(truth):
    """校验: 起点能到达所有敌方/地雷/返程点; 敌方蓝面停靠位可用"""
    blocked = {rc for rc, info in truth.items()
               if info[0] in (BUCKET, FRIEND)} | set(line_cells(*GREEN_LINE))
    from collections import deque
    start = name2rc(START_TILE)
    seen = {start}
    q = deque([start])
    while q:
        r, c = q.popleft()
        for dr, dc, _h in DIR4:
            nb = (r + dr, c + dc)
            if 0 <= nb[0] < ROWS and 0 <= nb[1] < COLS \
                    and nb not in blocked and nb not in seen:
                seen.add(nb)
                q.append(nb)
    if name2rc(RETURN_TILE) not in seen:
        return False
    for rc, info in truth.items():
        if info[0] in (TARGET, EXPLOSIVE) and rc not in seen:
            return False
        if info[0] == TARGET:            # 敌方蓝面停靠位必须可用
            blue = info[1]
            if blue is None:
                return False
            s = (rc[0] + blue[0], rc[1] + blue[1])
            if not (0 <= s[0] < ROWS and 0 <= s[1] < COLS):
                return False
            if s in truth or s in blocked or s in (start, name2rc(RETURN_TILE)):
                return False
    return True

def seg_turns(cells):
    """一段格点序列内的转弯次数"""
    turns = 0
    pd = None
    for i in range(1, len(cells)):
        d = sub(cells[i], cells[i - 1])
        if pd is not None and d != pd:
            turns += 1
        pd = d
    return turns

def compress(route, roles):
    """航点压缩: 只保留起点/拐点/角色点, 直线段小车全速行驶;
    同一(格,角色)只标注一次, 返程再次路过不重复标角色。
    航点给出格子正中心坐标(cm): 小车沿格心到格心行驶, 保证压过爆炸物正中心"""
    n = len(route)
    keep = {0}
    for i in range(1, n):
        d_in = sub(route[i], route[i - 1])
        d_out = sub(route[i + 1], route[i]) if i + 1 < n else None
        if roles.get(route[i]) or i == n - 1 or d_in != d_out:
            keep.add(i)
    pts = []
    emitted = set()
    for i in sorted(keep):
        role = roles.get(route[i])
        if (route[i], role) in emitted:
            role = None
        elif role:
            emitted.add((route[i], role))
        if i == 0:
            head = DIR_NAME.get(sub(route[1], route[0])) if n > 1 else None
        else:
            head = DIR_NAME.get(sub(route[i], route[i - 1]))
        pts.append({"cell": rc2name(route[i]), "heading": head, "role": role,
                    "x_cm": round((route[i][1] + 0.5) * TILE_CM, 1),
                    "y_cm": round((route[i][0] + 0.5) * TILE_CM, 1)})
    return pts

def estimate_time(route, roles):
    t = 0.0
    pd = None
    for i in range(1, len(route)):
        d = sub(route[i], route[i - 1])
        t += CELL_TIME_S
        if pd is not None and d != pd:
            t += TURN_TIME_S
        pd = d
    if any(r == "stop_face" for r in roles.values()):
        t += FACING_PAUSE_S
    if any(r == "hit" for r in roles.values()):
        t += FALL_TIMES * FALL_INTERVAL
    return t

def render_map(field, route=None, roles=None, car=None, title=""):
    """ASCII 矩阵渲染(纯标准库, 无 cv2 时使用)"""
    route_set = set(route or [])
    roles = roles or {}
    lines = [title]
    lines.append("     " + "".join(f"{c:2d}" for c in range(1, COLS + 1)))
    for r in range(ROWS):
        row = f" {ROW_LETTERS[r]}  "
        for c in range(COLS):
            rc = (r, c)
            role = roles.get(rc)
            if car == rc:
                ch = "@"
            elif role == "stop_face":
                ch = "S"
            elif role == "hit":
                ch = "T"
            elif role == "return":
                ch = "R"
            elif role == "explosive":
                ch = "x"
            elif rc in route_set and field.state(rc) not in (BUCKET, LINE, FRIEND):
                ch = "+"
            elif field.is_bridge(rc) and field.state(rc) == EMPTY:
                ch = "="
            else:
                ch = SYM[field.state(rc)]
            row += " " + ch
        lines.append(row)
    lines.append("图例: .未知 #障碍 x地雷 T敌方(蓝面) F我方(不打) |绿线 =桥洞 +路径 S蓝面停靠位 R返程 @小车")
    return "\n".join(lines)

def detect_blue_dir(roi):
    """识别打击区蓝色面朝向(有蓝面=敌方, 无蓝面=我方):
    蓝块质心在 ROI 中偏向哪侧, 蓝面就朝哪侧"""
    hsv = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
    mask = cv2.inRange(hsv, (90, 50, 50), (140, 255, 255))
    if int(mask.sum()) < 500:
        return None
    m = cv2.moments(mask)
    if m["m00"] == 0:
        return None
    cx = m["m10"] / m["m00"]
    cy = m["m01"] / m["m00"]
    h, w = roi.shape[:2]
    dx, dy = cx - w / 2, cy - h / 2
    # 像素 -> 场地方向: x 镜像(dx>0 即场地左/W), y 同向(dy>0 即场地下/S)
    if abs(dx) >= abs(dy):
        return (0, -1) if dx > 0 else (0, 1)
    return (1, 0) if dy > 0 else (-1, 0)

def __init__(self):
    self.grid = [[{"state": UNKNOWN, "known": False, "blue": None}
                  for _ in range(COLS)] for _ in range(ROWS)]
    for rc in line_cells(*GREEN_LINE):
        self.set(rc, LINE)          # 绿线是比赛规则, 开局已知, 无需扫描
    self.bridge = {name2rc(n) for n in BRIDGE_CELLS}   # 桥洞可通行, 仅作标记

def target_rc(self):
    """第一个敌方打击区(带蓝面)"""
    for r in range(ROWS):
        for c in range(COLS):
            if self.grid[r][c]["state"] == TARGET:
                return (r, c)
    return None

def known_of(self, state):
    return [(r, c) for r in range(ROWS) for c in range(COLS)
            if self.grid[r][c]["state"] == state]

def blocked_set(self):
    return {(r, c) for r in range(ROWS) for c in range(COLS)
            if self.field.grid[r][c]["state"] in (BUCKET, LINE, FRIEND)}

def a_star(self, start, goal, turn_pen=TURN_PEN, extra_avoid=()):
    """带转弯代价的 A*: 障碍/我方区/绿线禁入, 未知格视为可通行"""
    if start == goal:
        return [start]
    blocked = self.blocked_set() | set(extra_avoid)
    g = {(start[0], start[1], 0, 0): 0.0}
    came = {}
    heap = [(man(start, goal), 0.0, start[0], start[1], 0, 0)]
    while heap:
        f, _, r, c, dr, dc = heapq.heappop(heap)
        if (r, c) == goal:
            path = [(r, c)]
            node = (r, c, dr, dc)
            while node in came:
                pr, pc, pdr, pdc = came[node]
                path.append((pr, pc))
                node = (pr, pc, pdr, pdc)
            return path[::-1]
        for ndr, ndc, _h in DIR4:
            nr, nc = r + ndr, c + ndc
            if not (0 <= nr < ROWS and 0 <= nc < COLS):
                continue
            if (nr, nc) in blocked:
                continue
            extra = turn_pen if (dr, dc) != (0, 0) and (ndr, ndc) != (dr, dc) else 0.0
            ng = g[(r, c, dr, dc)] + 1.0 + extra
            key = (nr, nc, ndr, ndc)
            if ng < g.get(key, 1e18):
                g[key] = ng
                came[key] = (r, c, dr, dc)
                heapq.heappush(heap, (ng + man((nr, nc), goal), ng, nr, nc, ndr, ndc))
    return None

def shoot_candidates(self, t, blue):
    """蓝色面对面停靠位: 优先蓝面正对格, 其次其他 3 邻域(被挡时退避)"""
    order = []
    if blue is not None:
        order.append(tuple(blue))
    for d in DIR4:
        if tuple(d[:2]) not in order:
            order.append(d[:2])
    blocked = self.blocked_set()
    out = []
    for dr, dc in order:
        s = (t[0] + dr, t[1] + dc)
        if 0 <= s[0] < ROWS and 0 <= s[1] < COLS and s not in blocked and s != t:
            out.append(s)
    return out

def strike_cell(self, cur, t):
    """为敌方打击区选择蓝面停靠位(严格优先蓝面正对格)"""
    blue = self.field.blue(t)
    cands = self.shoot_candidates(t, blue)
    chosen = None
    if blue is not None:
        s_blue = (t[0] + blue[0], t[1] + blue[1])
        if s_blue in cands and self.a_star(cur, s_blue) is not None:
            chosen = s_blue
    if chosen is None:
        best = None
        for s in cands:
            p = self.a_star(cur, s)
            if p is None:
                continue
            cost = route_cost(p)
            if best is None or cost < best[0]:
                best = (cost, s)
        chosen = best[1] if best else None
    return chosen

